"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["55666"],{96389(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.modelo_de_documento.formato_nao_editavel","status":422,"titulo":"O modelo \xe9 um documento edit\xe1vel: DOCX ou ODT"},"descricao":{"codigo":"uniplus.selecao.modelo_de_documento.formato_nao_editavel","requisitos":[],"oQueAconteceu":["O modelo de documento \xe9 o arquivo que o candidato baixa, preenche e devolve, por isso precisa ser\\num documento edit\xe1vel: `DOCX` ou `ODT`. O in\xedcio do envio trouxe `formato` ausente ou com outro\\nvalor, como PDF ou imagem, que n\xe3o s\xe3o edit\xe1veis. O valor \xe9 conferido com a grafia exata, em\\nmai\xfasculas.","A recusa vem junto das demais viola\xe7\xf5es do mesmo pedido, no array `errors[]`, com o campo\\n`formato`. Pode aparecer ao lado de\\n[`nome_arquivo_invalido`](/erros/uniplus.selecao.modelo_de_documento.nome_arquivo_invalido)."],"comoResolver":["Informe `formato` como `DOCX` ou `ODT` e envie um arquivo desse formato. Se o modelo s\xf3 existe em\\nPDF, gere a vers\xe3o edit\xe1vel no programa em que o documento foi escrito. Se a resposta trouxer mais\\nde uma viola\xe7\xe3o em `errors[]`, corrija todas antes de repetir o in\xedcio do envio."],"ondeAparece":["In\xedcio do envio de modelo de documento"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Modelo de documento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);